<template>
<section class="analysis-overview" :class="{'stock-overview':Boolean(overview),compact,'swarm-overview':swarm}" aria-label="Analysis overview">
<header class="overview-heading"><span class="heading-icon"><ResearchIcon name="network"/></span><div><h2>{{ flow.title }}</h2><p v-if="overview?.savedCounts">{{ overview.savedCounts }}</p><p v-else-if="hasParticipants">{{ run.opinions?.length||0 }} of {{ participants.analysts.length }} analyst views saved · {{ run.trader_dialogue?.openings?.length||0 }} of {{ participants.traders.length }} trader views saved</p><p v-else>Your uploaded chart is saved. Agent discussion starts after the chart is read.</p><small v-if="flow.reuse">Earlier discussion reused</small></div></header>
<aside v-if="['failed','interrupted','cancelled','complete_with_gaps'].includes(run.status)" class="stopped-notice" role="status"><p>{{ run.failure?.message||run.error||(overview&&run.status==='complete_with_gaps'&&run.verdict?'Assessment saved with disclosed evidence gaps. Recorded messages remain available.':'The analysis stopped. Completed messages remain saved.') }}</p><details v-if="run.failure"><summary>Failure details & recovery</summary><p v-if="run.failure.contract">Contract: {{ run.failure.contract }}</p><p v-if="run.failure.previous_stage||run.failure.phase">Stopped phase: {{ run.failure.previous_stage||run.failure.phase }}</p><ul v-if="run.failure.errors?.length"><li v-for="(error,index) in run.failure.errors" :key="index">{{ error.loc?.length?error.loc.join('.'):'Contract invariant' }} · {{ error.type }}</li></ul><p v-else>Field-level diagnostics are not available for this saved failure.</p><p>{{ run.failure.recovery }}</p></details></aside>
<ol class="overview-stages" aria-label="Analysis stages"><li v-for="(step,index) in stages" :key="step.label" :class="step.state"><span>{{ step.state==='done'?'✓':index+1 }}</span><b>{{ step.label }}</b></li></ol>
<div v-if="hasParticipants||events.length" class="playback-toolbar"><button v-if="unread" class="new-message-action" @click="resumeFollowing">{{ unread }} new recorded messages · Follow live</button><span>{{ replaying?'Replay of saved discussion · no AI requests':run.status==='running'?'Messages appear when recorded work finishes':'Recorded conversation · not a live model session' }}</span><div v-if="swarm&&events.length" class="replay-speed" role="group" aria-label="Replay speed"><span>Replay</span><button v-for="speed in [1,2,4]" :key="speed" :aria-pressed="replaySpeed===speed" :class="{selected:replaySpeed===speed}" @click="setReplaySpeed(speed)">{{ speed }}×</button></div><button v-if="events.length" @click="replaying?stopReplay():startReplay()">{{ replaying?'Stop replay':'Replay saved discussion' }}</button></div>
<div class="overview-workspace" :class="{'without-chart':!$slots.chart,'no-participants':!hasParticipants}"><aside v-if="$slots.chart" class="overview-chart"><slot name="chart"/></aside><div v-if="hasParticipants" class="overview-right" :class="{'dual-population':swarm&&participants.analysts.length&&participants.traders.length}"><AgentPlayground :minimum-height="swarm?170:210" :swarm="swarm" :motion-duration="swarm?(replaying?1.2/replaySpeed:.6):1.2" v-if="participants.analysts.length" :people="participants.analysts" :events="events.filter(e=>e.lens==='specialists')" :title="overview?.analystLabel||'Analysts'" lens="specialists" :seed="run.id+'-analysts'" :generation-active="run.status==='running'" :spotlight-people="spotlight.people" :selected-event-ids="spotlight.eventIds" :sender-id="spotlight.sender" :receiver-ids="spotlight.people.filter(id=>id!==spotlight.sender)" :focus="focus||spotlight.sender" :active="activeEvent?.lens==='specialists'&&!paused?activeEvent:null" :evidence="Boolean(run.observation||run.dossier)" :hub-label="run.dossier?'Research brief':'Chart evidence'" @select="focusPerson" @discussion="$emit('discussion',$event)"/><AgentPlayground :minimum-height="swarm?170:210" :swarm="swarm" :motion-duration="swarm?(replaying?1.2/replaySpeed:.6):1.2" v-if="participants.traders.length" :people="participants.traders" :events="events.filter(e=>e.lens==='traders')" :title="overview?.traderLabel||'Traders'" lens="traders" :seed="run.id+'-traders'" :generation-active="run.status==='running'" :spotlight-people="spotlight.people" :selected-event-ids="spotlight.eventIds" :sender-id="spotlight.sender" :receiver-ids="spotlight.people.filter(id=>id!==spotlight.sender)" :focus="focus||spotlight.sender" :active="activeEvent?.lens==='traders'&&!paused?activeEvent:null" :evidence="Boolean(run.observation||run.dossier)" :hub-label="run.dossier?'Research brief':'Chart evidence'" @select="focusPerson" @discussion="$emit('discussion',$event)"/></div><div v-if="hasParticipants||events.length" class="overview-messages"><AgentMessageView :people="allPeople" :events="replaying?replayShown:paused?held:shown" :focus="focus" :paused="paused" :replaying="replaying" :running="run.status==='running'" :selected-event-id="selectedMessage?.id||''" @message="selectMessage" @select="selectFocus" @hold="pauseFeed" @toggle-follow="togglePause" @discussion="$emit('discussion',$event)"/></div></div>
</section>
</template>
<script setup>
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import ResearchIcon from './ResearchIcon.vue'
import AgentPlayground from './AgentPlayground.vue'
import AgentMessageView from './AgentMessageView.vue'
import {analysisFlow} from '../utils/analysisFlow.mjs'
import {overviewParticipants,overviewEvents,overviewStages} from '../utils/analysisOverview.mjs'
import {watchParticipantSelection} from '../utils/participantSelection.mjs'
import {newRecordedEvents,messageSpotlight} from '../utils/agentInteraction.mjs'
import {playbackEvents} from '../utils/playground.mjs'
const props=defineProps({run:{type:Object,required:true},overview:{type:Object,default:null},compact:Boolean,swarm:Boolean,selectedId:{type:String,default:undefined}})
const emit=defineEmits(['discussion','select'])
const participants=computed(()=>props.overview?.participants||overviewParticipants(props.run)),flow=computed(()=>props.overview?.flow||analysisFlow(props.run)),stages=computed(()=>props.overview?.stages||overviewStages(props.run)),events=computed(()=>props.overview?.events||overviewEvents(props.run))
const hasParticipants=computed(()=>participants.value.analysts.length>0||participants.value.traders.length>0)
const allPeople=computed(()=>[...participants.value.analysts.map(p=>({...p,lens:'specialists'})),...participants.value.traders.map(p=>({...p,lens:'traders'}))])
const replaySpeed=ref(props.swarm?4:1)
const focus=ref(''),paused=ref(false),shown=ref(events.value),held=ref([]),activeEvent=ref(null),replaying=ref(false),replayShown=ref([])
const selectedMessage=ref(null),unread=ref(0),arrivals=ref([]);const spotlight=computed(()=>messageSpotlight(selectedMessage.value||(!paused.value?activeEvent.value:null)))
let motionTimer,replayTimer,replayQueue=[]
function flash(event){clearTimeout(motionTimer);activeEvent.value=event;motionTimer=setTimeout(()=>{activeEvent.value=null},props.swarm?(replaying.value?1400/replaySpeed.value:900):1400)}
watch(events,next=>{const incoming=newRecordedEvents(shown.value,next);shown.value=next;if(!incoming.length)return;if(paused.value||replaying.value){unread.value+=incoming.length;arrivals.value.push(...incoming);return}const fresh=incoming.filter(e=>!e.reused);selectedMessage.value=fresh.at(-1)||selectedMessage.value;if(fresh.length)flash(fresh.at(-1))},{deep:true})
function replayStep(){replayTimer=null;if(!replaying.value||paused.value)return;if(!replayQueue.length){activeEvent.value=null;return}const event=replayQueue.shift();replayShown.value=[...replayShown.value,event];flash(event);replayTimer=setTimeout(replayStep,1500/replaySpeed.value)}
function setReplaySpeed(speed){replaySpeed.value=speed;if(replaying.value&&!paused.value){clearTimeout(replayTimer);replayTimer=setTimeout(replayStep,1500/speed)}}
function startReplay(){clearTimeout(replayTimer);selectedMessage.value=null;unread.value=0;focus.value='';paused.value=false;replaying.value=true;replayShown.value=[];replayQueue=playbackEvents(events.value).map((e,index)=>({...e,replayKey:e.id+':replay:'+index}));replayStep()}
function stopReplay(){clearTimeout(replayTimer);clearTimeout(motionTimer);replaying.value=false;activeEvent.value=null;replayQueue=[];replayShown.value=[];paused.value=false}
function pauseFeed(){activeEvent.value=null;if(!paused.value){held.value=shown.value;paused.value=true;clearTimeout(replayTimer)}}
function togglePause(){if(paused.value){resumeFollowing()}else pauseFeed()}
function resumeFollowing(){const latest=arrivals.value.filter(e=>!e.reused).at(-1);paused.value=false;unread.value=0;arrivals.value=[];focus.value='';selectedMessage.value=null;if(replaying.value)replayStep();else if(latest)flash(latest)}
function selectMessage(event){pauseFeed();selectedMessage.value=event;focus.value=event.author;emit('select',event.author)}
function selectFocus(id){pauseFeed();focus.value=id;selectedMessage.value=[...shown.value].reverse().find(event=>event.author===id||event.recipients.includes(id))||null;emit('select',id)}
function focusPerson(id){selectFocus(focus.value===id?'':id)}
watchParticipantSelection(()=>props.selectedId,focus,()=>{pauseFeed();selectedMessage.value=null})
watch(()=>props.run.id,()=>{clearTimeout(motionTimer);stopReplay();unread.value=0;arrivals.value=[];selectedMessage.value=null;shown.value=events.value;focus.value='';held.value=[];paused.value=false})
onBeforeUnmount(()=>{clearTimeout(motionTimer);clearTimeout(replayTimer)})
</script>
<style scoped>
.analysis-overview{margin:18px 0;color:#283340}.overview-heading{display:flex;align-items:center;gap:15px}.heading-icon{width:48px;height:48px;border-radius:50%;background:#fff0e8;color:#ff4f00;display:grid;place-items:center;flex:0 0 48px}.heading-icon svg{width:25px;height:25px}.overview-heading h2{font-size:25px;font-weight:600;letter-spacing:-.6px;margin:0 0 6px}.overview-heading p{font-size:12px;color:#687d96;margin:0}.overview-heading small{font-size:10px;color:#aa856b;display:block;margin-top:5px}.overview-stages{display:flex;list-style:none;padding:0;margin:14px 0;gap:12px}.overview-stages li{flex:1;display:flex;align-items:center;gap:9px;color:#8795a8;font-size:11px}.overview-stages li:not(:last-child):after{content:'';height:1px;flex:1;background:#e0e7ef;margin-left:5px}.overview-stages span{width:29px;height:29px;flex:0 0 29px;border:1px solid #d6e0ea;border-radius:50%;display:grid;place-items:center}.overview-stages b{font-weight:500}.overview-stages .done{color:#498569}.done span{background:#428f68;border-color:#428f68;color:white}.overview-stages .active{color:#ca5c27}.active span{background:#ff6b22;border-color:#ff6b22;color:white}.stopped span{border-color:#b7836e;color:#ad6245}.playback-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:11px 0 14px;font-size:10px;color:#8796a9}.playback-toolbar button{border:1px solid #efdccf;border-radius:5px;padding:6px 10px;background:#fff9f5;color:#a65d33;font-size:10px;cursor:pointer}.overview-workspace{display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.1fr);grid-template-areas:'chart agents' 'messages agents';gap:15px 20px;align-items:start}.overview-chart{grid-area:chart;min-width:0}.overview-right{grid-area:agents;min-width:0}.overview-messages{grid-area:messages;min-width:0}.without-chart{grid-template-areas:'agents messages';grid-template-columns:minmax(0,1.1fr) minmax(0,1fr)}@media(max-width:1000px){.overview-workspace{gap:13px}.overview-heading h2{font-size:22px}.overview-stages li{font-size:10px;gap:6px}}@media(max-width:620px){.overview-workspace,.without-chart{grid-template-columns:1fr;grid-template-areas:'chart' 'agents' 'messages';gap:13px}.overview-heading h2{font-size:20px}.overview-heading p{font-size:11px;line-height:1.6}.overview-stages{display:grid;grid-template-columns:1fr 1fr;gap:10px}.overview-stages li:after{display:none}.playback-toolbar{align-items:start}.playback-toolbar>span{line-height:1.6}.playback-toolbar button{white-space:nowrap}.without-chart{grid-template-areas:'agents' 'messages'}}

.compact .overview-heading,.compact .overview-stages{display:none}.analysis-overview.compact{margin:0}.compact.without-chart{margin:0}.compact .playback-toolbar{margin-top:0}.compact .overview-workspace.without-chart{grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);grid-template-areas:'agents messages';gap:16px}

.stopped-notice{border-left:2px solid #b9825d;background:#fff8f2;border-radius:3px;padding:10px 13px;margin:12px 0;color:#8b6247;font-size:12px;line-height:1.65}.stopped-notice p{margin:0}.stopped-notice summary{font-size:11px;cursor:pointer;margin-top:5px}.stopped-notice details p{margin-top:7px}.stopped-notice ul{padding-left:18px;font-size:11px}

.new-message-action{color:#bd5826!important;border-color:#f0cbb5!important;background:#fff5eb!important}.overview-right{border-radius:10px}.playback-toolbar{flex-wrap:wrap}.overview-messages :deep(.dm-view){box-shadow:0 4px 20px #2c455608}

@media(max-width:700px){.compact .overview-workspace.without-chart{grid-template-columns:1fr;grid-template-areas:'agents' 'messages'}}
</style>

<style scoped>
.no-participants.overview-workspace{grid-template-columns:minmax(0,780px);grid-template-areas:"chart"}
</style>
